    "description": "Configuración de economía, vuelos, cosméticos, Resource Pack y RPG en español",
    "content": "# =========================================================\n# CYTRICOS RPG - CONFIGURACIÓN GENERAL Y SISTEMAS (v7.0)\n# Desarrolladores Líderes: Dandan_13 & Wolfit12\n# Configuración 100% editable por Administradores\n# =========================================================\n\ngeneral_settings:\n  debug_mode: false\n  save_interval_seconds: 300\n  enable_luckperms_integration: true\n  enable_vault_integration: true\n  # Los jugadores nuevos inician sin raza hasta elegir una en /razas\n  default_race: \"none\"\n  # Desactivado por defecto para aislar la Tablist del sufijo de chat\n  inject_luckperms_chat_suffix: false\n\n# =========================================================\n# MOTOR DE ALMACENAMIENTO PERSISTENTE (YAML o MYSQL)\n# =========================================================\nstorage:\n  # Tipo de almacenamiento: YAML (archivos individuales en userdata/) o MYSQL (HikariCP)\n  type: \"YAML\"\n  mysql:\n    host: \"localhost\"\n    port: 3306\n    database: \"cytricos_races\"\n    username: \"cytricos\"\n    password: \"password_segura_123\"\n    table_prefix: \"cr_\"\n    pool:\n      maximum_pool_size: 10\n      minimum_idle: 5\n      connection_timeout: 30000\n      idle_timeout: 600000\n      max_lifetime: 1800000\n\n# =========================================================\n# LÍMITES DE ALTITUD DE VUELO (TECHO MÁGICO)\n# =========================================================\nflight_settings:\n  # Altura máxima en bloques sobre el suelo para Hadas (vuelo místico rasante)\n  fairy_max_height: 16.0\n  # Altura máxima en bloques sobre el suelo para Ángeles (Nivel 3+)\n  angel_max_height: 28.0\n\n# =========================================================\n# SISTEMA UNIFICADO DE METAMORFOSIS Y TRANSFORMACIÓN\n# =========================================================\ntransformations:\n  # Altitud Y absoluta máxima para transformaciones voladoras (editable en AdminGUI)\n  max-flight-y: 160.0\n  durations:\n    level_1: 20\n    level_2: 35\n    level_3: 50\n    level_4: 75\n    level_5: 110\n    level_6: -1\n\n# =========================================================\n# PUNTOS DE TALENTO POR ASESINATOS Y FRAGMENTOS\n# =========================================================\ntalent_points:\n  # Cada X bajas de criaturas otorga +1 Punto de Talento Racial (editable en AdminGUI)\n  kills_per_point: 64\n\ntalent_shard:\n  # Probabilidad de caída (0.0 a 1.0) del Fragmento de Talento Racial al derrotar mobs hostiles\n  drop_chance: 0.03\n\n# =========================================================\n# ENCICLOPEDIA INTERACTIVA (LIBRO ESCRITO)\n# =========================================================\nencyclopedia:\n  use_glyphs: false\n\n# =========================================================\n# AJUSTES DE COMBATE Y HABILIDADES ESPECÍFICAS\n# =========================================================\nvampire_mechanics:\n  solar_damage_tick_interval: 20\n  feeding_chance: 0.35\n  feeding_hunger_restored: 2\n  feeding_saturation_restored: 2.0\n  blood_broth_hunger: 6\n  blood_broth_saturation: 6.0\n\ngoblin_theft:\n  cooldown_seconds: 45\n  base_chance: 0.20\n  per_level_chance: 0.05\n  drop_at_feet_on_full_inventory: true\n\n# =========================================================\n# COSMÉTICOS INDEPENDIENTES, ALAS 3D Y RESOURCE PACK\n# (100% Gratuito: NO requiere ItemsAdder ni Oraxen)\n# =========================================================\ncosmetics_settings:\n  auras_enabled: true\n  wings:\n    enabled: true\n    use_display_entities: true\n    particles_enabled: true\n    animation_period_ticks: 2\n    allow_vault_unlock: true\n  resource_pack:\n    enabled: true\n    local_file: \"CytricosRaces-ResourcePack.zip\"\n    url: \"\"\n    sha1: \"\"\n    required: false\n    prompt: \"&e&lCYTRICOS RPG &7- Instala el paquete de recursos gratuito para ver las alas 3D animadas y reliquias.\"\n\nrpg_systems:\n  skill_tree_enabled: true\n  quests_enabled: true\n  achievements_enabled: true\n  encyclopedia_enabled: true\n\nrace_change_settings:\n  # Estado global del sistema (Modificable por /raza admin cambios parar | iniciar)\n  global_changes_enabled: true\n\n  # Permitir 1 selección / cambio de raza gratuito por jugador (Token inicial)\n  allow_one_free_change: true\n\n  # Sistema de Pago por Economía (Vault Integration)\n  economy_change:\n    enabled: true\n    cost: 50000.0\n    currency_symbol: \"$\"\n\n  # Sistema de Cambio por Objeto Especial con Lore Custom\n  custom_item_change:\n    enabled: true\n    consume_item_on_use: true\n    item_spec:\n      material: \"NETHER_STAR\"\n      custom_model_data: 10099\n      display_name: \"&6&lEsencia de Reencarnación Ancestral\"\n      lore:\n        - \"&7Este artefacto sagrado permite moldear\"\n        - \"&7tu linaje físico y alma mística.\"\n        - \"\"\n        - \"&e&lUSO ÚNICO:\"\n        - \"&aPermite cambiar de Raza 1 vez en /razas.\"\n        - \"\"\n        - \"&c&lEXCLUSIVO CYTRICOS RPG - OBJETO ADMINISTRATIVO\"\n      glow: true\n\nmessages:\n  prefix: \"&8[&eCYTRICOS&8] \"\n  changes_paused: \"&c&l[CYTRICOS] &7El sistema de cambios de raza se encuentra pausado temporalmente por la administración.\"\n  free_change_used: \"&a&l[CYTRICOS] &7¡Has utilizado tu selección de raza gratuita única!\"\n  paid_change_success: \"&a&l[CYTRICOS] &7Cambio de raza realizado con éxito por &e$%cost%&7.\"\n  item_change_success: \"&a&l[CYTRICOS] &7Has entregado tu &6Esencia de Reencarnación &7y cambiado de raza.\"\n  no_funds_or_item: \"&c&l[CYTRICOS] &7No posees el cambio gratuito, ni el dinero suficiente ($%cost%), ni el Objeto Especial.\"\n  already_in_race: \"&cYa perteneces a esta raza.\"\n  race_changed: \"&e&l[CYTRICOS] &7Tu raza ha sido cambiada a: &a%race%\"\n  level_up_success: \"&a&l[CYTRICOS] &7¡Has ascendido al Nivel %level% de %race%!\"\n  level_max: \"&e&l[CYTRICOS] &7Ya te encuentras en el nivel máximo legendario.\"\n  insufficient_reqs: \"&c&l[CYTRICOS] &7No cumples con los requisitos de materiales o dinero ($%cost%) para ascender.\"\n  not_found_player: \"&cJugador no encontrado.\"\n  no_permission: \"&cNo tienes permisos para ejecutar este comando.\"\n"
